classDiagram
    class Vehicle {
        +String make
        +String model
        +int year
        +start() void
        +stop() void
    }
    class Car {
        +int doors
        +openTrunk() void
    }
    class Engine {
        +int horsepower
        +ignite() void
    }
    class Driver {
        +String name
        +drive(Vehicle v) void
    }
    Vehicle <|-- Car
    Car *-- Engine : contains
    Driver --> Vehicle : drives

